    if n <= 1:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_min_level(n, k, cards):
    dp = [float('inf')] * (k + 1)
    dp[0] = 0  # Base case: zero level is always possible with sum 0

    # Iterate over each card to update the DP table
    for p, c, l in cards:
        for sum_power in range(k, p - 1, -1):
            if sum_power + c <= k:
                dp[sum_power + c] = min(dp[sum_power + c], (lp := l) + dp[sum_power - p - 1])

    # If the answer is still infinity, it's impossible to build the deck
    return dp[k] if dp[k] != float('inf') else -1

