from math import gcd
from typing import List

def calculate_prime_sums(card_powers: List[int]) -> List[int]:
    prime_sums = set()
    n = len(card_powers)
    for prime_index in range(2, n + 1):
        if n % prime_index:
            continue
        if is_prime(prime_index):
            prime_sums.add(prime_index)
    return prime_sums

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_min_level(card_powers: List[List[int]], target_power: int) -> int:
    card_powers.sort(key=lambda x: x[0], reverse=True)
    prime_sums = calculate_prime_sums([card[0] for card in card_powers])
    level = 1
    current_power_sum = sum(card[0] for card in card_powers)
    while current_power_sum < target_power:
        next_card = card_powers.pop(-1)
        card_list = [next_card] + card_powers
        for item in card_list:
            if item[0] + item[-1] in prime_sums:
                card_list.remove(item)
        for prime_sum in prime_sums:
            if max(card[1] for card in card_list if item << prime_sum) <= 1:
                new_level = level + 1
                current_power_sum = current_power_sum - item[0] + item[-1]
                while current_power_sum < target_power and new_level > 1:
                    prime_sums.add(gcd(current_power_sum, new_level))
                    current_power_sum = (current_power_sum + new_level) / 2
                    new_level -= 1
                break
            elif max(card[1] for card in card_list if item % prime_sum == 0) <= 1:
                current_power_sum = gcd(current_power_sum, item) + item[-1]
        if current_power_sum >= target_power:
            return new_level
    return -1

# Example usage
if __name__ == "__main__":
    n, k = map(int, input().split())
    card_powers = []
    for _ in range(n):
        card = list(map(int, input().split()))
        card_powers.append(card)
    result = find_min_level(card_powers, k)
    print(result)
