from math import comb, gcd
from functools import reduce
from collections import defaultdict
from operator import mul
INF = int(1e18)
MOD = int(1e9) + 7

def solve(N, M, abundances):
    abundances = list(sorted(abundances.items(), key=lambda x: x[0]))
    shortages = defaultdict(int)
    for i, (a, b) in enumerate(abundances):
        A, B = a
        if b > 0:
            shortages[A + 1] += b
        if b < 0:
            shortages[A - 1] -= b
    if shortages[A]:
        return 0
    T = reduce(mul, map(abs, combinations_with_replacement_1(N, sum(shortages.values()) + 1)), 1)
    return T - M + 1

def combinations_with_replacement_1(n, k):
    A = [INF] * (k + 1)
    A[0] = 1
    for a in range(n + 1):
        for b in range(k + 1):
            A[b] = min(A[b], a + 1)
            if b < k:
                A[b + 1] = min(A[b + 1], a + 1)
    return [A[b] for b in range(k + 1)]

def main():
    T = int(input())
    results = []
    for _ in range(T):
        N, M = map(int, input().split())
        abundances = defaultdict(int)
        for i in range(N):
            x, y = map(int, input().split())
            if y > 0:
                abundances[x] += y
            elif y < 0:
                abundances[x] -= y
        results.append(solve(N, M, list(abundances.items())))
    for r in results:
        print(r)

