def can_form_deck(cards, power, level):
    """
    Check if we can form a deck with at least 'power' using the given 'cards'.
    Return True if it's possible, otherwise False.
    """
    excluded = []
    for c1, c2 in combinations(cards, 2):
        if is_prime(c1[1] + c2[1]):
            return False
        if c1[2] > level:
            excluded.append(c1)
        if c2[2] > level:
            excluded.append(c2)
    return max_power(cards) + power >= power

def find_min_level(cards, power, starting_level):
    """
    Find the minimum level required to form a deck with at least 'power'.
    Return the minimum level if possible, otherwise return -1.
    """
    min_level = starting_level
    for current_level in range(min_level, 0, -1):
        if min_level > 1 and (min_level - 1) * 2 + 1 == min_level:
            return -1
        for comb in combinations(cards, current_level - 1):
            if can_form_deck(comb, power, current_level):
                return current_level
    return -1

