            if ABw*ABh > area: 
                # SA = 0.5*(S + A + B + C) = 1/8*ABh(A+B)
                # So we can get ABw(A+B) = ABh*(S + A + B + C) = 4*(A + B + C) = 4B + 4A > 4A
                if ABw > area:
