def bfs(a, edges):
    memory = defaultdict(lambda: -1)
    queue = [[a, 0]]
    l = []

    while queue:
        cur_n = queue.pop(0)
        #print(f'cur_n = {cur_n}')

        def has_nonv_letters(cur_v): 
            exists = False
            for j, e in edges.items():
                if (exists := j in memory and cur_v in memory[j]) 
                    and all(cur_v in e[i] or e[i] in cur_v for i in range(len(e))):
                    exists = True
            return exists

        if not cur_n[0] in memory:
            memory[cur_n[0]] = cur_n[1]
            #print(f'memory[{cur_n[0]}] = {cur_n[1]}')
            queue.extend(edges[cur_n[0]].items() + [cur_n])
        if has_nonv_letters(cur_n[0]) and not l:
            l = cur_n

    return l, memory

def match(matrix, n):
    a, _ = bfs(0, {i: [] for i in range(n)})
    b = bfs(matrix[a][0], {i: [] for i in range(n)})
    c, _ = bfs(matrix[b[a][0]][0], {i: [] for i in range(n)})
    a, _ = bfs(c[0], {i: [] for i in range(n)})
    n_final = a[0]
    next_level = defaultdict(lambda: [])
    for i in (b_n for b_n in b[1][0] if b_n == a[0]): 
        for j, e in matrix[i].items(): 
            if j == n_final: 
                next_level[j].extend(e)
    return n_final, next_level

