def find_minimum_distance(test_cases):
    distances = []
    for case in test_cases:
        N, M, W, H = map(int, case.split())
        directions = case.read()
        points = []
        for _ in range(M):
            X, Y = list(map(int, input().split()))
            points.append((X, Y))

        # Given directions are always valid
        layers = defaultdict(list)
        for direction in directions:
            if direction == 'U':
                layers[(0, H)].append(points.pop(0))
            elif direction == 'R':
                layers[(W - 1, H - 1)].append(points.pop(0))
            elif direction == 'L':
                layers[(W - 1, Y)].append(points.pop(0))
            elif direction == 'D':
                layers[(X, H - 1)].append(points.pop(0))

        # For each layer, find the minimum distance between any two points
        min_distance = float('inf')
        for layer in layers:
            distances.extend([euclidean_distance(p, p) for p in points])

        # Calculate the minimum distance after unfolding
        for i in range(len(distances)):
            for j in range(i, len(distances), 2):
                distance = euclidean_distance(distances[i:j], 
                                              distances[i:(j + 1) + (2 * (i + j) % 2) % len(distances)])
                min_distance = min(min_distance, distance())

        min_distance /= 2
        print(min_distance)

