                        if next_last_letter - 1 == c[i]:
                            res = (res + dp(index + 1, 1, i)) % mod
                    else:
                        res = (res + dp(index + 1, 1, i) + dp(index + 1, next_carry, i)) % mod
                elif i > 0:
                    res = (res + dp(index + 1, 1, i) + dp(index + 1, next_carry, i)) % mod
        return res

    return dp(0, 0, -1)

