from functools import lru_cache

def z(a, k):
    @lru_cache(maxsize=None)
    def z_helper(a, k):
        if len(a) < k:
            return 0
        ans = 0
        for i in range(len(a) - k + 1):
            temp = a[i]
            for j in range(i, i + k):
                temp = max(temp, a[j])
            ans = (ans + temp) % (10**9 + 7)
        return ans + z_helper(a[1:], k)

    return z_helper(tuple(a), k)

