from functools import cache

mod = 998244353

@cache
def countStrings(a, b, c, cnt):
    if cnt == 1:
        return a + b + c
    subcnt = 0
    if a and (not b or not c):
        subcnt += (a + b) * countStrings('', b, c, min(cnt - 1, a))
        subcnt %= mod
    if (not a or b) and (not c):
        subcnt += (a + c) * countStrings(a, '', b, min(cnt - 1, b))
        subcnt %= mod
    if (not a or c) and (not b):
        subcnt += (b + c) * countStrings(a, b, '', min(cnt - 1, c))
        subcnt %= mod
    return (a * subcnt + b * subcnt + c * subcnt) % mod

def solve(S):
    return countStrings(*[1 if v == 'a' else 0 for v in S])

