from collections import defaultdict, deque

def find_possible_labels(n, m, roads):
    adj_list = defaultdict(list)
    for u, v in roads:
        adj_list[u - 1].append(v - 1)
        adj_list[v - 1].append(u - 1)

    visited = [False] * n
    dist = [-1] * n

    def bfs(start):
        q = deque([start])
        visited[start] = True
        dist[start] = 0

        while q:
            u = q.popleft()
            for v in adj_list[u]:
                if not visited[v]:
                    visited[v] = True
                    dist[v] = dist[u] + 1
                    q.append(v)

    bfs(0)
    bfs(n - 1)

    valid_labels = []
    for i in range(n):
        for next_node in adj_list[i]:
            if dist[next_node] == dist[i] + 1:
                if dist[next_node] % 2 == 0:
                    valid_labels.append(dist[next_node] // 2)
                else:
                    valid_labels.append((dist[next_node] - 1) // 2)

    if len(valid_labels) != n:
        return "NO"

    return "YES\n" + " ".join(map(str, valid_labels))

