MOD = 10**9 + 7

def get_power(a, n):
    s = 1
    t = a
    while n:
        if n & 1:
            s = (s * t) % MOD
        t = (t * t) % MOD
        n >>= 1
    return s

def solve(n, k, q):
    a = []
    for _ in range(n):
        a.append([0])
    for i in range(n):
        for j in range(a[i][0], 1000010):
            a[i].append(-((j + 1) // i - (j // i) + 1) * get_power(j // i, MOD-2) % MOD)

    dp = [0] * (k + 1)
    for i in range(q):
        m = 0
        c = [0]
        for j in range(n + 1):
            t = 0
            for q in range(j):
                if a[q][m] > 0:
                    c[q] += a[q][m]
                    t = c[q]
                else:
                    t = c[q]

            if t > 0:
                dp[k] += t
            if k == 1:
                dp[k] %= MOD
            else:
                dp[0 - min(m, k)] += t // min(m, k)
            m = min(m, k)

        dp.sort(reverse=True)
        for j in range(k):
            c[j] %= MOD
            dp[j] %= MOD
            dp[j] = (dp[j] * a[j][m] + c[j]) % MOD

        for j in range(k):
            dp[j] = (dp[j] + dp[j-1]) % MOD

    return sum(dp) % MOD

