    """Find the minimum level needed to build a deck with the required power."""
    total_power = 0
    prime_sums = set()
    for card in cards:
        total_power += card[0]
        if is_prime(total_power):
            prime_sums.add(total_power)
    min_level = float('inf')
    for card in cards:
        level = ceil(card[2] * (total_power - card[0] + card[1]) / card[1])
