    maxs[0] = 1
    for i in range(len(arr)):
        for j in range(m, -1, -1):
            if j > 0 and arr[i] > arr[i-1]:
                maxs[j] += maxs[j-1]
            maxs[j] %= p
    return maxs[m]

@lru_cache(maxsize=None)
def count_perm(m, k):
    if m == 0:
        return 0
    if m == 1:
        return 0 if k == 0 else 1
    if k <= 0 or m < k:
        return 0
    if not perm:
        return 0
    res = 0
    cur = perm[0]
    found = 0
    total = 0
    for i in range(m):
        if cur < perm[i]:
            found += 1
        cur = perm[i]
    while True:
        res += find_max(perm[i+1:], m - k - found)
        cur = perm[i+1]
        found += 1
        if found == k:
            break
        total += 1
        while found > m:
            if perm[i] > perm[total]:
                found -= 1
            perm[i] = perm[total]
            perm[total] -= 1
            found -= 1
            total += 1
    res %= p
    return res * count_perm(m-1, k) % p

