def solve(a, m, n, p):
    mod = 1000000007

    # Precompute powers of 2 and 3 modulo p
    two_pow = [1]
    three_pow = [1]
    prev_two_exp = 0
    prev_three_exp = 0

    for i in range(1, n):
        if i % 2 == 1:
            two_pow.append((two_pow[-1] * 2) % p)
        else:
            two_pow.append((two_pow[-1] * 2) % p)

        if i % 3 == 0:
            three_pow.append((three_pow[-1] * 3) % p)
        else:
            three_pow.append((three_pow[-1] * 3) % p)

        two_exp = pow(2, i, p) - pow(2, prev_two_exp - 1, p) - two_pow[i] + two_pow[prev_two_exp - 1]
        three_exp = pow(3, i, p) - pow(3, prev_three_exp - 1, p) - three_pow[i] + three_pow[prev_three_exp - 1]

        prev_two_exp = i % 2
        prev_three_exp = i % 3

    # Check if modulo a power of 2 or 3 then it is divisible by p % ni^2 and ni^3
    def check_pf_divisible_by_p(ni):
        if ni == 0: 
            return False

        for i in range(1, n):
            if (ni * two_pow[i] * 3 % p - 7 * two_pow[i] % p) % p:
                return False

            if (ni * two_pow[i] * 9 % p - 7 * two_pow[i] % p) % p:
                return False

            if (ni * three_pow[i] * 3 % p - 7 * three_pow[i] % p) % p:
                return False

            if (ni * three_pow[i] * 9 % p - 7 * three_pow[i] % p) % p:
                return False

        return True

    if check_pf_divisible_by_p(a + m):
        return four_divide_modulo_p(a + m, a + m)

    def field_split_divisor (num):
        divisor = num // two_pow[a]
        result = num % divisor

        if result >= (divisor // 2 * one_third_modulo_p(a + m, two_pow)): 
            result -= divisor // 2 * one_third_modulo_p(a + m, two_pow)

        return result

    if a + m == 0:
        return 1

    if check_pf_divisible_by_p(a):
        return field_split_divisor(a)

    return field_split_divisor(a % p)

def four_divide_modulo_p(num, p):
    target = (mod - num + p * (p - 1)) % p
    def equal_divide(num, target):
        result = pow(p, num) % p

        if num == 0:
            return 1
        if num >= target: 
            return 0
        result *= equal_divide(num + target, target)
        result %= p

        return result

    result = pow(p, num % (target)) % p
    for i in range(num // target):
        result *= equal_divide(num, target)
        result %= p

    return result

def one_third_modulo_p(i, power):
    a = gcd(i, power)
    i /= a
    power /= a

    numerator = (i - 1) * (power - 1)
    if numerator <= 0:
        return 0
    numerator += a

    denominator = 3 * (power - 1)
    if denominator == 0:
        return 1

    return numerator // denominator % p
