from typing import List

def z(a: List[int], k: int) -> int:
    if len(a) < k:
        return 0
    else:
        b = [0] * k
        ans = 0
        for i in range(k):
            temp = a[i]
            for j in range(i, i + k):
                temp = max(temp, a[j])
            b = b[:i] + b[i:k] + [temp] + b[k:]
            ans = (ans + temp) % (10**9 + 7)
        return ans + z(b, k)

def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    print(z(a, k))

if __name__ == "__main__":
    solve()
