from collections import defaultdict

def get_combinations_solutions(s):
    n = len(s)
    mod = 998244353

    # Initialize combinations to hold solutions for each possible length
    combinations = defaultdict(list)
    all_solutions = set()

    # Helper function to compute combinations for a given length
    def expand_combinations(iteratee, s):
        if not s:
            all_solutions.add(iteratee)
            return
        for i in range(len(s)):
            if s[i] in ["a", "b", "c"]:
                new_s = list(s)
                new_s[i] = s[i]
                iteratee(new_s)

    # Function to find all combinations for a given length
    def find_combinations(length):
        combinations[length] = defaultdict(list)

        for i in range(length):
            expand_combinations(combinations[length], s[i-1:i+2])  # length can be 1 or 2
            for c in combinations[length-1]:
                expand_combinations(combinations[length], c)  # combined with combination of lengths 1-2

    # Initialize combinations for length 2
    find_combinations(2)

    # Adjust for the case where length is 1
    combinations[1] = {"aaa", "bbb", "ccc", "a", "b", "c"}

    # Convert combinations to list and store them
    combinations = sorted(combinations.items(), key=lambda x: len(x[1]))

    # Get number of solutions by iterating through length and filtering combinations
    for combo_len, combinations in combinations:
        if len(s) <= combo_len:
            all_solutions |= (combinations if len(combinations) > 1 else combinations[0])

    return pow(len(all_solutions), 2, mod)

s = input()
print(get_combinations_solutions(s))
